  // src/favpop.js
  function openFavFolderPop(btn, opts) {
    var favorited = !!opts.favorited;
    var state = { on: favorited };
    return openPickPop(btn, {
      title: opts.title || (favorited ? "调整收藏夹" : "选择收藏夹"),
      multi: true,
      requireSelection: !favorited,
      // 未收藏不许提交空勾选；已收藏允许"全取消=移除收藏"
      emptyText: "还没有收藏夹",
      load: function() {
        return folderList(opts.acId).then(function(items) {
          var its = items.map(function(f) {
            return { id: f.id, name: f.name, count: f.count, on: !!f.inFolder };
          });
          if (!favorited && its.length && !its.some(function(it) {
            return it.on;
          })) its[0].on = true;
          return { items: its };
        });
      },
      canCreate: {
        label: "＋ 新建收藏夹",
        placeholder: "收藏夹名（1~40 字）",
        maxLen: 40,
        check: folderNameError,
        create: function(name) {
          return folderAdd(name);
        }
        // → 新夹 id（响应 data.folderId）
      },
      confirm: function(sel) {
        var req;
        if (!favorited) req = favAdd(opts.acId, sel.ids);
        else if (!sel.ids.length) req = favRemove(opts.acId, sel.removed);
        else req = favUpdate(opts.acId, sel.added, sel.removed);
        return req.then(function(ok) {
          if (ok) {
            state.on = sel.ids.length > 0;
            state.ids = sel.ids.slice();
          }
          return ok;
        });
      },
      done: function() {
        toast(state.on ? "已加入收藏" : "已取消收藏");
        if (opts.done) opts.done({ favorited: state.on, ids: state.ids || [] });
      }
    });
  }

  // src/banpop.js
  function toggleBananaPop(btn, opts) {
    var host4 = btn.parentNode;
    var existing = host4 && host4.querySelector(".acsv-banpop");
    if (existing) {
      existing.remove();
      return;
    }
    if (!host4) return;
    var pop = el("div", "acsv-banpop");
    var opts5 = [];
    var sending = false;
    var build = function(n2) {
      var ob = el("button");
      ob.title = "投 " + n2 + " 根香蕉";
      var img = el("img");
      img.alt = "";
      img.src = VIDEO_ICONS.banana;
      img.addEventListener("error", function() {
        ob.textContent = n2;
      });
      ob.appendChild(img);
      ob._img = img;
      ob.addEventListener("mouseenter", function() {
        opts5.forEach(function(o, i) {
          o._img.src = i < n2 ? VIDEO_ICONS.bananaOn : VIDEO_ICONS.banana;
        });
      });
      ob.addEventListener("click", function(ev) {
        ev.stopPropagation();
        if (sending) return;
        sending = true;
        pop.remove();
        opts.send(n2).then(function(ok) {
          if (ok) {
            if (opts.applied) opts.applied(n2);
            toast("投出 " + n2 + " 根香蕉");
          } else {
            errBanana();
          }
        }, function() {
          errBanana();
        });
      });
      opts5.push(ob);
      pop.appendChild(ob);
    };
    for (var n = 1; n <= 5; n++) build(n);
    pop.addEventListener("mouseleave", function() {
      opts5.forEach(function(o) {
        o._img.src = VIDEO_ICONS.banana;
      });
    });
    if (getComputedStyle(host4).position === "static") host4.style.position = "relative";
    host4.appendChild(pop);
    if (opts.anchorBtn) {
      var hl = host4.getBoundingClientRect(), bl = btn.getBoundingClientRect();
      pop.style.right = Math.round(hl.right - bl.right) + "px";
    }
    closeOnOutsideClick(pop, [btn], function() {
      pop.remove();
    });
  }

  // src/rail.js
